// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz: from, v, single recipient address in array (as an address param and a boolean to decide whether recipient is a special contract)
    // We need at least one fuzz parameter; use address to be fuzzed plus uint256 value.
    function testFuzz_property(address from, address toAddr, uint256 v) public {
        // Keep inputs wide but avoid zero-length _tos: we will construct an array of length 1 always (admissible domain requires length>0).
        address[] memory tos = new address[](1);
        tos[0] = toAddr;

        // The external call from c uses caddress.call(...). A raw EOA (fuzzed address) will accept the call and return success=true.
        // To exercise the call path and have observable behavior we deploy a RecordingHelper that exposes the exact signature
        // transferFrom(address,address,uint256) and records calls. We'll pass its address as caddress so the call decodes and succeeds.
        RecordingHelper helper = new RecordingHelper();

        // Prepare to call c.transfer. Use try/catch to capture whether the call reverted.
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: if the call completed (ok == true), the reference implementation always returns true.
        // We assert that ok implies that invoking the function via low-level call returns true when called via address(c).call.
        // To read the actual boolean return value from c.transfer we perform a low-level call with same inputs and decode the returned bool.
        // Construct calldata for transfer(address,address,address[],uint256)
        bytes4 sig = bytes4(keccak256("transfer(address,address,address[],uint256)"));
        bytes memory data = abi.encodeWithSelector(sig, from, address(helper), tos, v);

        // perform low-level call to capture returned boolean without invoking solidity's ABI dispatch that would revert on false return
        (bool success, bytes memory ret) = address(c).call(data);

        // If the high-level call reverted, success will be false. The reference guarantees: when success==true, returned bool is true.
        bool returnedTrue = false;
        if (success && ret.length >= 32) {
            returnedTrue = abi.decode(ret, (bool));
        }

        // Exactly one assertion: the reference satisfies that whenever the call completes (success==true), the returned bool is true.
        // The mutant (which returns false) will make this assertion fail for inputs where the call completes.
        assertTrue(!success || returnedTrue);
    }
}

// Recording helper that matches the selector transferFrom(address,address,uint256)
contract RecordingHelper {
    event Called(address from, address to, uint256 v);
    // exact signature so abi.decode works in call
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true; // succeed to allow c to continue
    }
}
